const F={"frontend/src/app/dashboard/orders/page.tsx": "\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { useCurrency } from \"../../../lib/currency\";\nimport {\n  ShoppingCart, Search, Filter, Download, Zap,\n  Package, Truck, Check, X, Clock, RefreshCw,\n  ChevronDown, Eye, ArrowUpRight, MoreHorizontal,\n  User, MapPin, Phone, Mail, Calendar,\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", cyan: \"#06B6D4\" };\nconst T = {\n  dark:  { card: \"#181230\", border: \"rgba(255,255,255,0.06)\", text: \"#fff\", muted: \"rgba(255,255,255,0.38)\", faint: \"rgba(255,255,255,0.04)\", row: \"rgba(255,255,255,0.02)\" },\n  light: { card: \"#fff\",    border: \"rgba(15,5,32,0.07)\",    text: \"#0D0918\", muted: \"rgba(13,9,24,0.45)\", faint: \"rgba(15,5,32,0.03)\", row: \"rgba(15,5,32,0.015)\" },\n};\n\nconst STATUS: Record<string, { label: string; color: string; bg: string; icon: any }> = {\n  PENDING:   { label: \"Pending\",   color: \"#F59E0B\", bg: \"rgba(245,158,11,0.12)\",  icon: Clock },\n  PAID:      { label: \"Paid\",      color: \"#10B981\", bg: \"rgba(16,185,129,0.12)\",  icon: Check },\n  SHIPPED:   { label: \"Shipped\",   color: \"#06B6D4\", bg: \"rgba(6,182,212,0.12)\",   icon: Truck },\n  DELIVERED: { label: \"Delivered\", color: V.v400,    bg: \"rgba(107,53,232,0.12)\",  icon: Package },\n  CANCELLED: { label: \"Cancelled\", color: \"#EF4444\", bg: \"rgba(239,68,68,0.12)\",   icon: X },\n  REFUNDED:  { label: \"Refunded\",  color: \"#8B5CF6\", bg: \"rgba(139,92,246,0.12)\",  icon: RefreshCw },\n};\n\nconst TABS = [\"All\", \"Pending\", \"Paid\", \"Shipped\", \"Delivered\", \"Cancelled\"];\n\nfunction fmt(n: number) {\n  return new Intl.NumberFormat(\"en\", { style: \"currency\", currency: \"NGN\", maximumFractionDigits: 0 }).format(n || 0);\n}\n\nfunction StatusBadge({ status }: { status: string }) {\n  const cfg = STATUS[status] || STATUS.PENDING;\n  const Icon = cfg.icon;\n  return (\n    <div className=\"inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold\"\n      style={{ background: cfg.bg, color: cfg.color }}>\n      <Icon size={10} />\n      {cfg.label}\n    </div>\n  );\n}\n\n// ── Order Detail Drawer ───────────────────────────────────────────────────────\nfunction OrderDrawer({ order, onClose, t, isDark }: { order: any; onClose: () => void; t: any; isDark: boolean }) {\n  const qc = useQueryClient();\n  const [newStatus, setNewStatus] = useState(order.status);\n  const [tracking, setTracking] = useState(order.trackingNumber || \"\");\n\n  const updateMut = useMutation({\n    mutationFn: () => api.put(`/orders/${order.storeId}/${order.id}`, { status: newStatus, trackingNumber: tracking }),\n    onSuccess: () => { toast.success(\"Order updated\"); qc.invalidateQueries({ queryKey: [\"orders\"] }); onClose(); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Update failed\"),\n  });\n\n  return (\n    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}\n      className=\"fixed inset-0 z-50 flex items-center justify-end\"\n      style={{ background: \"rgba(0,0,0,0.6)\", backdropFilter: \"blur(8px)\" }}\n      onClick={e => e.target === e.currentTarget && onClose()}>\n      <motion.div initial={{ x: \"100%\" }} animate={{ x: 0 }} exit={{ x: \"100%\" }} transition={{ type: \"spring\", damping: 28 }}\n        className=\"h-full w-full max-w-md overflow-y-auto\"\n        style={{ background: isDark ? \"#181230\" : \"#fff\", borderLeft: `1px solid ${t.border}` }}>\n\n        {/* Header */}\n        <div className=\"flex items-center justify-between px-5 py-4\" style={{ borderBottom: `1px solid ${t.border}` }}>\n          <div>\n            <h2 className=\"font-bold text-sm\" style={{ color: t.text }}>Order #{order.id?.slice(-8)?.toUpperCase()}</h2>\n            <p className=\"text-xs mt-0.5\" style={{ color: t.muted }}>{new Date(order.createdAt).toLocaleDateString(\"en\", { day: \"numeric\", month: \"short\", year: \"numeric\" })}</p>\n          </div>\n          <button onClick={onClose} style={{ color: t.muted }}><X size={18} /></button>\n        </div>\n\n        <div className=\"p-5 space-y-5\">\n          {/* Status */}\n          <div className=\"rounded-2xl p-4\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n            <p className=\"text-xs font-semibold mb-3\" style={{ color: t.muted }}>Order Status</p>\n            <div className=\"grid grid-cols-3 gap-2\">\n              {Object.entries(STATUS).map(([key, cfg]) => {\n                const Icon = cfg.icon;\n                return (\n                  <button key={key} onClick={() => setNewStatus(key)}\n                    className=\"flex flex-col items-center gap-1 p-2 rounded-xl text-center transition-all\"\n                    style={{ background: newStatus === key ? cfg.bg : \"transparent\", border: `1px solid ${newStatus === key ? cfg.color : t.border}` }}>\n                    <Icon size={13} style={{ color: newStatus === key ? cfg.color : t.muted }} />\n                    <span className=\"text-[10px] font-semibold\" style={{ color: newStatus === key ? cfg.color : t.muted }}>{cfg.label}</span>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n\n          {/* Tracking */}\n          <div>\n            <label className=\"block text-xs font-semibold mb-2\" style={{ color: t.muted }}>Tracking Number</label>\n            <input value={tracking} onChange={e => setTracking(e.target.value)} placeholder=\"e.g. GIG-12345678\"\n              className=\"w-full px-3 py-2.5 rounded-xl text-sm outline-none\"\n              style={{ background: t.faint, border: `1px solid ${t.border}`, color: t.text, fontFamily: \"inherit\" }} />\n          </div>\n\n          {/* Customer */}\n          <div className=\"rounded-2xl p-4\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n            <p className=\"text-xs font-semibold mb-3\" style={{ color: t.muted }}>Customer</p>\n            <div className=\"space-y-2\">\n              {[\n                { icon: User,    val: order.customerName || order.customer?.name },\n                { icon: Mail,    val: order.customerEmail || order.customer?.email },\n                { icon: Phone,   val: order.customerPhone || order.customer?.phone },\n                { icon: MapPin,  val: order.shippingAddress?.address || order.deliveryAddress },\n              ].filter(i => i.val).map(({ icon: Icon, val }) => (\n                <div key={val} className=\"flex items-center gap-2\">\n                  <Icon size={12} style={{ color: t.muted, flexShrink: 0 }} />\n                  <span className=\"text-xs truncate\" style={{ color: t.text }}>{val}</span>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          {/* Items */}\n          <div className=\"rounded-2xl p-4\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n            <p className=\"text-xs font-semibold mb-3\" style={{ color: t.muted }}>Items</p>\n            <div className=\"space-y-2\">\n              {(order.items || order.orderItems || []).map((item: any, i: number) => (\n                <div key={i} className=\"flex items-center gap-3\">\n                  <div className=\"w-8 h-8 rounded-lg overflow-hidden flex-shrink-0\"\n                    style={{ background: isDark ? \"rgba(255,255,255,0.06)\" : \"#f1f5f9\" }}>\n                    {item.product?.images?.[0]\n                      ? <img src={item.product.images[0]} alt=\"\" className=\"w-full h-full object-cover\" />\n                      : <Package size={12} style={{ color: t.muted, margin: \"auto\" }} />\n                    }\n                  </div>\n                  <div className=\"flex-1 min-w-0\">\n                    <p className=\"text-xs font-semibold truncate\" style={{ color: t.text }}>{item.product?.name || item.name || \"Product\"}</p>\n                    <p className=\"text-xs\" style={{ color: t.muted }}>Qty: {item.quantity} · {fmt(item.price)}</p>\n                  </div>\n                  <p className=\"text-xs font-bold\" style={{ color: t.text }}>{fmt((item.price || 0) * (item.quantity || 1))}</p>\n                </div>\n              ))}\n            </div>\n            <div className=\"flex justify-between mt-3 pt-3\" style={{ borderTop: `1px solid ${t.border}` }}>\n              <span className=\"text-xs font-semibold\" style={{ color: t.muted }}>Total</span>\n              <span className=\"text-sm font-black\" style={{ color: \"#10B981\" }}>{fmt(order.total || order.totalAmount)}</span>\n            </div>\n          </div>\n\n          {/* Save */}\n          <button onClick={() => updateMut.mutate()} disabled={updateMut.isPending}\n            className=\"w-full py-3 rounded-xl text-sm font-bold text-white flex items-center justify-center gap-2 transition-all hover:opacity-90 disabled:opacity-60\"\n            style={{ background: `linear-gradient(135deg, ${V.v500}, #3D1C8A)` }}>\n            {updateMut.isPending ? \"Saving...\" : \"Save Changes\"}\n          </button>\n        </div>\n      </motion.div>\n    </motion.div>\n  );\n}\n\n// ── Main Page ─────────────────────────────────────────────────────────────────\nexport default function OrdersPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = isDark ? T.dark : T.light;\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [activeTab, setActiveTab] = useState(\"All\");\n  const [search, setSearch] = useState(\"\");\n  const [selectedOrder, setSelectedOrder] = useState<any>(null);\n  const qc = useQueryClient();\n\n  const fulfillMut = useMutation({\n    mutationFn: (orderId: string) => api.patch(`/orders/${storeId}/${orderId}/status`, { status: \"SHIPPED\" }),\n    onSuccess: () => { toast.success(\"Order fulfilled!\"); qc.invalidateQueries({ queryKey: [\"orders\"] }); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed to fulfill\"),\n  });\n\n  const { data, isLoading } = useQuery({\n    queryKey: [\"orders\", storeId, activeTab],\n    queryFn: () => api.get(`/orders/${storeId}${activeTab !== \"All\" ? `?status=${activeTab.toUpperCase()}` : \"\"}`).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  const orders: any[] = data?.orders || data || [];\n  const filtered = orders.filter(o =>\n    !search ||\n    o.id?.toLowerCase().includes(search.toLowerCase()) ||\n    (o.customerName || o.customer?.name || \"\").toLowerCase().includes(search.toLowerCase()) ||\n    (o.customerEmail || o.customer?.email || \"\").toLowerCase().includes(search.toLowerCase())\n  );\n\n  const stats = [\n    { label: \"Total Orders\",  value: orders.length,                                                    color: V.v400 },\n    { label: \"Pending\",       value: orders.filter((o: any) => o.status === \"PENDING\").length,          color: \"#F59E0B\" },\n    { label: \"Shipped\",       value: orders.filter((o: any) => o.status === \"SHIPPED\").length,          color: V.cyan },\n    { label: \"Revenue\",       value: fmt(orders.reduce((a: number, o: any) => a + (o.total || o.totalAmount || 0), 0)), color: \"#10B981\" },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1400, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}\n        className=\"flex items-start justify-between gap-4 mb-6\">\n        <div>\n          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: \"-0.03em\", color: t.text }}>Orders</h1>\n          <p style={{ fontSize: 13, color: t.muted, marginTop: 4 }}>Track and manage customer orders</p>\n        </div>\n        <div className=\"flex gap-2\">\n          <button className=\"flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold\"\n            style={{ border: `1px solid ${t.border}`, color: t.muted, background: t.card }}>\n            <Download size={12} /> Export\n          </button>\n          <button className=\"flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold\"\n            style={{ background: \"rgba(107,53,232,0.1)\", color: V.v300, border: \"1px solid rgba(107,53,232,0.2)\" }}>\n            <Zap size={12} /> KIRO Auto-fulfil\n          </button>\n        </div>\n      </motion.div>\n\n      {/* Stats */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5\">\n        {stats.map((s, i) => (\n          <motion.div key={s.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.07 }}\n            className=\"rounded-2xl p-4 relative overflow-hidden\"\n            style={{ background: t.card, border: `1px solid ${t.border}` }}>\n            <div className=\"absolute top-0 left-0 right-0 h-0.5\" style={{ background: `linear-gradient(90deg, transparent, ${s.color}60, transparent)` }} />\n            <p className=\"text-2xl font-black mb-1\" style={{ color: s.color }}>{s.value}</p>\n            <p className=\"text-xs font-semibold\" style={{ color: t.text }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Table */}\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}\n        className=\"rounded-2xl overflow-hidden\"\n        style={{ background: t.card, border: `1px solid ${t.border}` }}>\n\n        {/* Tabs + toolbar */}\n        <div style={{ borderBottom: `1px solid ${t.border}` }}>\n          <div className=\"flex items-center px-4 gap-0 overflow-x-auto\" style={{ scrollbarWidth: \"none\" }}>\n            {TABS.map(tab => (\n              <button key={tab} onClick={() => setActiveTab(tab)}\n                className=\"py-3.5 px-3 text-xs font-semibold whitespace-nowrap transition-all flex-shrink-0\"\n                style={{ borderBottom: `2px solid ${activeTab === tab ? V.v500 : \"transparent\"}`, color: activeTab === tab ? t.text : t.muted }}>\n                {tab}\n              </button>\n            ))}\n            <div className=\"flex-1\" />\n            <div className=\"flex items-center gap-2 py-2\">\n              <div className=\"flex items-center gap-2 px-3 py-2 rounded-xl\"\n                style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n                <Search size={12} style={{ color: t.muted }} />\n                <input value={search} onChange={e => setSearch(e.target.value)} placeholder=\"Search orders...\"\n                  className=\"bg-transparent border-none outline-none text-xs w-36\"\n                  style={{ color: t.text, fontFamily: \"inherit\" }} />\n              </div>\n            </div>\n          </div>\n        </div>\n\n        {/* Column headers */}\n        <div className=\"hidden md:grid px-4 py-2.5\" style={{ gridTemplateColumns: \"1fr 160px 90px 110px 110px 60px\", borderBottom: `1px solid ${t.border}` }}>\n          {[\"Customer\", \"Date\", \"Items\", \"Status\", \"Total\", \"\"].map((h, i) => (\n            <div key={i} className=\"text-[10px] font-bold uppercase tracking-wider\" style={{ color: t.muted, fontFamily: \"'Syncopate', sans-serif\" }}>{h}</div>\n          ))}\n        </div>\n\n        {/* Rows */}\n        <div className=\"divide-y\" style={{ borderColor: t.border }}>\n          {isLoading ? (\n            Array.from({ length: 5 }).map((_, i) => (\n              <div key={i} className=\"h-16 px-4 flex items-center gap-3 animate-pulse\">\n                <div className=\"h-3 rounded-full w-1/4\" style={{ background: t.faint }} />\n                <div className=\"h-3 rounded-full w-1/6\" style={{ background: t.faint }} />\n              </div>\n            ))\n          ) : filtered.length > 0 ? (\n            filtered.map((order, i) => (\n              <motion.div key={order.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03 }}\n                className=\"hidden md:grid items-center px-4 py-3 cursor-pointer transition-all hover:opacity-80\"\n                style={{ gridTemplateColumns: \"1fr 160px 90px 110px 110px 60px\" }}\n                onClick={() => setSelectedOrder(order)}>\n                <div>\n                  <p className=\"text-sm font-semibold\" style={{ color: t.text }}>{order.customerName || order.customer?.name || \"Customer\"}</p>\n                  <p className=\"text-xs mt-0.5\" style={{ color: t.muted }}>#{order.id?.slice(-8)?.toUpperCase()}</p>\n                </div>\n                <p className=\"text-xs\" style={{ color: t.muted }}>\n                  {new Date(order.createdAt).toLocaleDateString(\"en\", { day: \"numeric\", month: \"short\" })}\n                </p>\n                <p className=\"text-xs font-semibold\" style={{ color: t.text }}>\n                  {(order.items || order.orderItems || []).length} item{(order.items || order.orderItems || []).length !== 1 ? \"s\" : \"\"}\n                </p>\n                <StatusBadge status={order.status} />\n                <p className=\"text-sm font-bold\" style={{ color: \"#10B981\" }}>{fmt(order.total || order.totalAmount)}</p>\n                <button className=\"flex items-center justify-center w-7 h-7 rounded-lg transition-all hover:opacity-70\"\n                  style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n                  <Eye size={11} style={{ color: t.muted }} />\n                </button>\n              </motion.div>\n            ))\n          ) : (\n            <div className=\"flex flex-col items-center justify-center py-20 text-center\">\n              <div className=\"w-14 h-14 rounded-2xl flex items-center justify-center mb-4\"\n                style={{ background: \"rgba(6,182,212,0.1)\", border: \"1px solid rgba(6,182,212,0.2)\" }}>\n                <ShoppingCart size={24} color={V.cyan} />\n              </div>\n              <h3 className=\"font-bold text-sm mb-2\" style={{ color: t.text }}>\n                {search ? \"No orders found\" : \"No orders yet\"}\n              </h3>\n              <p className=\"text-xs mb-5\" style={{ color: t.muted, maxWidth: 300, lineHeight: 1.6 }}>\n                {search ? \"Try a different search\" : \"Once customers start buying, all orders appear here. KIRO can help you get your first sale.\"}\n              </p>\n              {!search && (\n                <button className=\"flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold text-white\"\n                  style={{ background: `linear-gradient(135deg, ${V.v500}, #3D1C8A)` }}>\n                  <Zap size={12} /> Ask KIRO to get first sales\n                </button>\n              )}\n            </div>\n          )}\n        </div>\n      </motion.div>\n\n      {/* Order detail drawer */}\n      <AnimatePresence>\n        {selectedOrder && <OrderDrawer order={selectedOrder} onClose={() => setSelectedOrder(null)} t={t} isDark={isDark} />}\n      </AnimatePresence>\n    </div>\n  );\n}\n", "backend/src/controllers/kai.controller.ts": "// ============================================================\n// KIRO — Complete Controller (10/10)\n// Path: backend/src/controllers/kai.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { PrismaClient } from \"@prisma/client\";\nimport {\n  callClaude, detectIntent, generateTitle, getQuickActions,\n} from \"../services/kai.service\";\nimport { validateAction, translateError, describeAction } from \"../utils/kai.actions\";\n// Note: getStoreContext replaced by getDeepContext globally\nimport { getDeepContext } from \"../services/kai.context\";\nimport { buildStoreBrain, decomposeGoal } from \"../services/kai.brain\";\nimport { buildIntelligencePrompt } from \"../services/kai.intelligence\";\nimport {\n  extractMemoriesFromConversation, getMemories, saveMemory,\n  deleteMemory, getActiveGoals, analyzeBrandVoice, getMemoryContext,\n  getRelevantMemories, buildCrossSessionContext, summarizeAndSaveConversation,\n} from \"../services/kai.memory.service\";\nimport {\n  getUnreadAlerts, markAlertRead, analyzeStore,\n} from \"../services/kai.pulse.service\";\nimport { getKaiSkills } from \"../services/kai.market.service\";\n\nconst prisma = new PrismaClient();\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// ── GET /api/kai/greeting ─────────────────────────────────────\nexport async function getGreeting(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n\n    const [ctx, alerts] = await Promise.all([\n      getDeepContext(storeId),\n      getUnreadAlerts(storeId),\n    ]);\n\n    const user      = (req as any).user;\n    const firstName = (user?.name || \"there\").split(\" \")[0];\n    const hour      = new Date().getHours();\n\n    const greeting = `Good ${new Date().getHours() < 12 ? \"morning\" : \"afternoon\"}! KIRO here.`;\n    const contextLine = ctx.revenueToday > 0 \n      ? `You've made ${ctx.currencySymbol}${ctx.revenueToday.toLocaleString()} today.`\n      : \"What are we working on today?\";\n    const quickActions = [\n      ...(ctx.pendingOrders > 0 ? [{ label:`Fulfill ${ctx.pendingOrders} orders`, icon:\"📬\", prompt:`Help me fulfill my ${ctx.pendingOrders} pending orders` }] : []),\n      ...(ctx.lowStockProducts.length > 0 ? [{ label:`${ctx.lowStockProducts.length} low stock`, icon:\"⚠️\", prompt:`Show me my low stock products` }] : []),\n      ...(ctx.totalProducts < 5 ? [{ label:\"Add more products\", icon:\"➕\", prompt:`Suggest 10 trending products for ${ctx.country}` }] : []),\n      ...(ctx.revenueToday === 0 ? [{ label:\"Get a sale today\", icon:\"🎯\", prompt:`I have ₦0 in sales today. Fastest way to get a sale?` }] : []),\n    ].slice(0, 4);\n\n    res.json({\n      success: true,\n      data: { greeting, name: firstName, contextLine, quickActions, storeContext: ctx, unreadAlerts: alerts.length },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversations ────────────────────────────────\nexport async function getConversations(req: Request, res: Response) {\n  try {\n    const userId = (req as any).user?.userId || (req as any).user?.id;\n    const { storeId } = req.query as { storeId?: string };\n    // Build where clause - use storeId if provided, else find by userId\n    const where: any = { archived: false };\n    if (storeId) where.storeId = storeId;\n    else where.userId = userId;\n\n    const conversations = await prisma.kaiConversation.findMany({\n      where,\n      orderBy: [{ pinned: \"desc\" }, { updatedAt: \"desc\" }],\n      select: {\n        id: true, title: true, pinned: true, createdAt: true, updatedAt: true,\n        messages: { orderBy: { createdAt: \"desc\" }, take: 1, select: { content: true, role: true } },\n      },\n    });\n    res.json({ success: true, data: conversations });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversation/:id ─────────────────────────────\nexport async function getConversation(req: Request, res: Response) {\n  try {\n    const conv = await prisma.kaiConversation.findUnique({\n      where: { id: req.params.id },\n      include: { messages: { orderBy: { createdAt: \"asc\" } } },\n    });\n    if (!conv) return res.status(404).json({ success: false, message: \"Not found\" });\n    res.json({ success: true, data: conv });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/smart-chat (STREAMING + MEMORY) ────────────\nexport async function smartChat(req: Request, res: Response) {\n  const { storeId, imageBase64, imageMediaType } = req.body;\n  const message = req.body.message || (imageBase64 ? \"Please analyse this image and help me use it in my store.\" : \"\");\n  const conversationId = req.body.conversationId || req.body.sessionId || null;\n  if (!message || !storeId)\n    return res.status(400).json({ success: false, message: \"message and storeId required\" });\n\n  try {\n    // Get or create conversation\n    let conv: any = conversationId\n      ? await prisma.kaiConversation.findUnique({\n          where: { id: conversationId },\n          include: { messages: { orderBy: { createdAt: \"asc\" }, take: 20 } },\n        })\n      : null;\n\n    if (!conv) {\n      const userId = (req as any).user?.userId || (req as any).user?.id;\n      if (!userId) return res.status(401).json({ success: false, message: \"User not found in token\" });\n      conv = await (prisma.kaiConversation as any).create({\n        data: { storeId, userId, title: generateTitle(message) },\n        include: { messages: true },\n      });\n    }\n\n    // Save user message\n    const userContent = message + (\n      req.body.fileName ? `\\n\\n[User attached file: ${req.body.fileName}]` : \"\"\n    ) + (\n      req.body.imageUrl ? `\\n\\n[User attached image: ${req.body.imageUrl}]` : \"\"\n    );\n    await (prisma.kaiMessage as any).create({\n      data: { conversationId: conv.id, role: \"user\", content: userContent },\n    });\n\n    // Get everything in parallel\n    const [ctx, intent] = await Promise.all([\n      getDeepContext(storeId).catch((e) => {\n        console.error(\"[KIRO] getDeepContext failed:\", e.message);\n        return null as any;\n      }),\n      Promise.resolve(detectIntent(message)),\n    ]);\n    if (!ctx) {\n      res.write(`data: ${JSON.stringify({ token: \"KIRO is warming up — store data loading. Try again in a moment.\" })}\n\n`);\n      res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id })}\n\n`);\n      res.end(); return;\n    }\n    const useSearch = [\"market_research\",\"trending\",\"analytics\"].includes(intent);\n\n    // Build rich conversation history - 20 messages, near full content\n    const historyMsgs = (conv.messages || []).slice(-20);\n    const history = historyMsgs\n      .map((m: any) => {\n        const who = m.role === \"user\" ? \"Owner\" : \"KIRO\";\n        const content = m.content.slice(0, 800); // much more context\n        return `${who}: ${content}`;\n      })\n      .join(\"\\n\");\n    \n    // Load cross-session memory (conversation summaries + ongoing tasks)\n    let crossSessionContext = \"\";\n    try {\n      const userId = (req as any).user?.userId || (req as any).user?.id;\n      crossSessionContext = await buildCrossSessionContext(storeId, userId, conv.id, message);\n    } catch {}\n\n    // Build complete system prompt (includes memory, goals, brand voice, market data)\n    let memories = \"\";\n    try { memories = await getRelevantMemories(storeId, message); } catch {}\n\n    // Build the store brain\n    let brain: any = undefined;\n    try { brain = await buildStoreBrain(storeId, ctx); } catch(e: any) {\n      console.error(\"[KIRO] Brain build failed:\", e.message);\n    }\n\n    // Multi-step goal detection — decompose complex requests\n    let goalPlan = \"\";\n    try { goalPlan = decomposeGoal(message, ctx, brain); } catch {}\n\n    let systemPrompt: string;\n    try {\n      systemPrompt = buildIntelligencePrompt(ctx, history, crossSessionContext, memories, brain);\n    } catch(e: any) {\n      console.error(\"[KIRO] buildCompleteSystemPrompt failed, using fallback:\", e.message);\n      systemPrompt = `You are KIRO, an AI business assistant for ${ctx.storeName}. Be helpful, concise and actionable.`;\n    }\n\n    // Build messages array\n    const claudeMsgs: any[] = [];\n    // Use 8 msgs for simple/text, 12 for complex — saves tokens\n    const historyDepth = (imageBase64 || intent !== \"general\") ? 12 : 8;\n    for (const m of (conv.messages || []).slice(-historyDepth)) {\n      claudeMsgs.push({ role: m.role, content: m.content });\n    }\n    // Current message (with optional image)\n    // Intent-aware routing — give KIRO a specific directive based on what the user wants\n    const intentDirective: Record<string, string> = {\n      analytics:        \"[DIRECTIVE: User wants analytics. Show real numbers from STORE DATA. Compare periods. Identify trends. End with one growth action.]\",\n      product_management:\"[DIRECTIVE: User wants product help. Refer to their actual product list. Help them add/edit/improve. Generate content if needed.]\",\n      order_management: \"[DIRECTIVE: User wants order help. Check their pending orders list. Offer to fulfill. Give tracking advice.]\",\n      customer_insights:\"[DIRECTIVE: User wants customer intel. Use customer data. Segment by value. Suggest retention actions.]\",\n      market_research:  \"[DIRECTIVE: User wants market trends. Draw on Nigerian ecommerce knowledge. Give specific product names and price ranges.]\",\n      promotions:       \"[DIRECTIVE: User wants promotions. Create a coupon or flash sale with specifics. Write the copy too.]\",\n      marketing:        \"[DIRECTIVE: User wants marketing. Write the actual copy — Instagram caption, WhatsApp message, TikTok script. Make it ready to post.]\",\n      content:          \"[DIRECTIVE: User wants content. Generate full product description or ad copy. Nigerian audience. Conversion-focused.]\",\n      pricing:          \"[DIRECTIVE: User wants pricing help. Analyze their current prices vs Nigerian market. Give specific recommended prices with margin calculation.]\",\n      general:          \"[DIRECTIVE: Look at today's priority actions and proactively surface the most important thing they should know or do right now.]\",\n    };\n    const directive = intentDirective[intent] || intentDirective.general;\n    const enhancedMessage = `${message}\n\n${directive}`;\n\n    const currentContent: any[] = [];\n    // Handle image — either base64 or URL\n    let finalImageBase64 = imageBase64;\n    let finalImageMediaType = imageMediaType || \"image/jpeg\";\n    const imageUrl = req.body.imageUrl;\n    \n    // If URL provided but no base64, fetch the image\n    if (!finalImageBase64 && imageUrl && !imageUrl.startsWith(\"data:\")) {\n      try {\n        const imgRes = await fetch(imageUrl);\n        const imgBuf = await imgRes.arrayBuffer();\n        finalImageBase64 = Buffer.from(imgBuf).toString(\"base64\");\n        finalImageMediaType = imgRes.headers.get(\"content-type\") || \"image/jpeg\";\n      } catch(e) {\n        console.error(\"[KIRO] Could not fetch image URL:\", e);\n      }\n    }\n    \n    // If it's a data URI, strip the prefix\n    if (finalImageBase64?.startsWith(\"data:\")) {\n      const parts = finalImageBase64.split(\",\");\n      finalImageMediaType = parts[0].split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n      finalImageBase64 = parts[1];\n    }\n    \n    console.log(\"[KIRO] Image:\", {\n      hasBase64: !!finalImageBase64,\n      mediaType: finalImageMediaType,\n      size: finalImageBase64?.length || 0,\n    });\n    \n    if (finalImageBase64 && finalImageMediaType) {\n      currentContent.push({ type: \"image\", source: { type: \"base64\", media_type: finalImageMediaType, data: finalImageBase64 } });\n    }\n    currentContent.push({ type: \"text\", text: enhancedMessage });\n    claudeMsgs.push({ role: \"user\", content: currentContent.length === 1 ? message : currentContent });\n\n    // Stream response\n    res.setHeader(\"Content-Type\", \"text/event-stream\");\n    res.setHeader(\"Cache-Control\", \"no-cache\");\n    res.setHeader(\"Connection\", \"keep-alive\");\n\n    let fullResponse = \"\";\n\n    // Detect message complexity for model selection\n    const msgLower = message.toLowerCase().trim();\n    const isSimple = /^(hi|hello|hey|thanks|ok|okay|yes|no|sure|great|nice|cool|what.*name|who are you|good\\s*(morning|afternoon|evening|night)|my name is)[\\s!?.]*$/i.test(message.trim());\n    \n    // Use haiku for simple messages (37x higher rate limit, 5x cheaper)\n    // Use sonnet for complex queries and all vision\n    const useHaiku = isSimple && !finalImageBase64;\n    await callClaude({\n      systemPrompt,\n      messages: claudeMsgs,\n      useSearch,\n      model: finalImageBase64 ? \"claude-sonnet-4-6\" : (useHaiku ? \"claude-haiku-4-5-20251001\" : \"claude-sonnet-4-6\"),\n      maxTokens: finalImageBase64 ? 4096 : (useHaiku ? 1024 : 4096),\n      onToken: (token) => {\n        fullResponse += token;\n        res.write(`data: ${JSON.stringify({ token, conversationId: conv.id })}\\n\\n`);\n      },\n    });\n\n    // Parse KIRO_ACTION — handles every format KIRO might output\n    const parsedActions: any[] = [];\n    let cleanResponse = fullResponse;\n    try {\n      // Step 1: normalize all variants to KIRO_ACTION:{...}\n      let work = fullResponse\n        .replace(/KIRO_ACTION\\s*```json?\\s*/gi, \"KIRO_ACTION:\")   // code block start\n        .replace(/```\\s*$/gm,                        \"\")           // code block end\n        .replace(/KIRO_ACTION\\s*:\\s*\\n\\s*/g,      \"KIRO_ACTION:\") // colon + newline\n        .replace(/KIRO_ACTION\\s+(?=\\{)/g,           \"KIRO_ACTION:\"); // space instead of colon\n\n      // Step 2: extract all JSON objects after KIRO_ACTION marker\n      const re = /KIRO_ACTION[:\\s]+?\\s*(\\{(?:[^{}]|\\{(?:[^{}]|\\{[^{}]*\\})*\\})*\\})/g;\n      let m: RegExpExecArray | null;\n      while ((m = re.exec(work)) !== null) {\n        try {\n          const obj = JSON.parse(m[1]);\n          if (obj.action && !obj.type) obj.type = obj.action; // normalize field name\n          if (obj.type && obj.payload) parsedActions.push(obj);\n          else if (obj.type) parsedActions.push({ type: obj.type, payload: obj });\n        } catch {\n          // Try extracting from full match if parse fails\n          try {\n            const cleaned = m[1].replace(/\\n/g,\" \").replace(/\\s+/g,\" \");\n            const obj = JSON.parse(cleaned);\n            if (obj.action && !obj.type) obj.type = obj.action;\n            parsedActions.push(obj);\n          } catch {}\n        }\n      }\n      // Step 3: strip all KIRO_ACTION blocks from user-visible text\n      cleanResponse = fullResponse\n        .replace(/KIRO_ACTION\\s*```[\\s\\S]*?```/gi, \"\")\n        .replace(/KIRO_ACTION[:\\s]+\\{[\\s\\S]*?\\}(?=\\s|$)/g, \"\")\n        .replace(/\\n{3,}/g, \"\\n\\n\")\n        .trim();\n    } catch {}\n\n    // Save KIRO response (clean version)\n    await (prisma.kaiMessage as any).create({\n      data: {\n        conversationId: conv.id,\n        role:     \"assistant\",\n        content:  cleanResponse,\n        metadata: { intent, searched: useSearch, actions: parsedActions },\n      },\n    });\n\n    await prisma.kaiConversation.update({\n      where: { id: conv.id },\n      data: { updatedAt: new Date() },\n    });\n\n    // Extract memories in background (don't await — don't slow down response)\n    if (apiKey()) {\n      extractMemoriesFromConversation(storeId, message, fullResponse, conv.id, apiKey())\n        .catch(err => console.error(\"Memory extraction error:\", err));\n    }\n\n    res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id, actions: parsedActions, cleanResponse })}\\n\\n`);\n    res.end();\n\n  } catch (err: any) {\n    console.error(\"KIRO error:\", err.message?.slice(0, 200));\n    \n    // Translate technical errors to human language\n    let humanMsg = \"KIRO is having a moment. Try sending that again.\";\n    const raw = (err.message || \"\").toLowerCase();\n    if (raw.includes(\"429\") || raw.includes(\"rate_limit\") || raw.includes(\"rate limit\")) {\n      humanMsg = \"I'm getting a lot of requests right now. Give me 30 seconds and ask again.\";\n    } else if (raw.includes(\"anthropic_api_key\") || raw.includes(\"api key\")) {\n      humanMsg = \"KIRO isn't fully configured yet. The API key needs to be set in Render settings.\";\n    } else if (raw.includes(\"timeout\") || raw.includes(\"econnreset\")) {\n      humanMsg = \"Connection timed out. Your store data is fine — just try again.\";\n    } else if (raw.includes(\"token\") || raw.includes(\"auth\") || raw.includes(\"401\")) {\n      humanMsg = \"Session expired. Refresh the page and try again.\";\n    }\n    \n    if (!res.headersSent) {\n      res.status(500).json({ success: false, message: humanMsg });\n    } else {\n      res.write(`data: ${JSON.stringify({ error: true, message: humanMsg })}\\n\\n`);\n      res.end();\n    }\n  }\n}\n\n// ── POST /api/kai/action ──────────────────────────────────────\nexport async function executeAction(req: Request, res: Response) {\n  const { conversationId, storeId, actions } = req.body;\n  if (!actions?.length) return res.status(400).json({ success: false, message: \"actions required\" });\n\n  const results = [];\n  for (const action of actions) {\n    if (!action.approved) continue;\n    try {\n      let result: any = null;\n      switch (action.type) {\n        case \"update_order_status\":\n          result = await prisma.order.update({ where: { id: action.payload.orderId }, data: { status: action.payload.status } });\n          break;\n        case \"create_coupon\":\n          result = await (prisma.coupon as any).create({\n            data: { storeId, code: action.payload.code, discountType: action.payload.discountType || \"PERCENTAGE\",\n              discountValue: action.payload.discountValue, isActive: true,\n              expiresAt: action.payload.expiresAt ? new Date(action.payload.expiresAt) : null },\n          });\n          break;\n        case \"update_price\":\n          result = await prisma.product.update({ where: { id: action.payload.productId }, data: { price: action.payload.price } });\n          break;\n\n        case \"add_product\": {\n          const pName = action.payload.name || \"Product\";\n          const pSlug = pName.toLowerCase()\n            .replace(/[^a-z0-9]+/g, \"-\")\n            .replace(/^-|-$/g, \"\")\n            .slice(0, 80) + \"-\" + Date.now().toString(36);\n          // Include image if provided in payload or from context\n          const pImages = action.payload.images?.length\n            ? action.payload.images\n            : action.payload.imageUrl\n            ? [action.payload.imageUrl]\n            : [];\n          result = await (prisma.product as any).create({\n            data: {\n              storeId:     action.payload.storeId || storeId,\n              name:        pName,\n              slug:        pSlug,\n              price:       Number(action.payload.price) || 0,\n              description: action.payload.description || \"\",\n              images:      pImages,\n              inventory:   Number(action.payload.inventory) || 100,\n              category:    action.payload.category || \"\",\n              status:      \"ACTIVE\",\n            },\n          });\n          break;\n        }\n\n        case \"update_stock\":\n          result = await (prisma.product as any).update({\n            where: { id: action.payload.productId },\n            data:  { inventory: Number(action.payload.quantity) },\n          });\n          break;\n\n        case \"create_discount\":\n          result = await (prisma.coupon as any).create({\n            data: {\n              storeId,\n              code:     action.payload.code,\n              discount: Number(action.payload.discount) || 10,\n              type:     action.payload.type || \"PERCENTAGE\",\n              maxUses:  Number(action.payload.maxUses) || 100,\n              expiresAt: action.payload.expiresAt ? new Date(action.payload.expiresAt) : null,\n            },\n          });\n          break;\n\n        case \"update_shipping\":\n          result = await (prisma.shippingZone as any).upsert({\n            where:  { id: action.payload.zoneId || \"new\" },\n            create: { storeId, name: action.payload.name, shippingRate: Number(action.payload.rate), estimatedDays: action.payload.days || \"3-5 days\", countries: [\"Nigeria\"] },\n            update: { shippingRate: Number(action.payload.rate) },\n          });\n          break;\n        case \"update_goal\":\n          const _userId = (req as any).user?.userId || (req as any).user?.id;\n          result = await (prisma.kaiGoal as any).upsert({\n            where: { id: action.payload.goalId || \"new\" },\n            create: { storeId, userId: (req as AuthRequest).user?.userId || (req as AuthRequest).user?.id || 'system', title: action.payload.title, targetValue: action.payload.targetValue,\n              currentValue: 0, unit: action.payload.unit, deadline: new Date(action.payload.deadline) },\n            update: { currentValue: action.payload.currentValue },\n          });\n          break;\n\n        case \"create_flash_sale\": {\n          // Create a time-limited sale by setting compare prices\n          const products = action.payload.productIds || [];\n          const discount = action.payload.discountPercent || 20;\n          result = await Promise.all(products.map((pid: string) =>\n            prisma.product.findUnique({ where: { id: pid } }).then(p => {\n              if (!p) return null;\n              return (prisma.product as any).update({\n                where: { id: pid },\n                data: { comparePrice: p.price, price: Math.round(p.price * (1 - discount/100)) },\n              });\n            })\n          ));\n          break;\n        }\n\n        case \"send_email\": {\n          // Queue an email campaign\n          result = { queued: true, subject: action.payload.subject, preview: action.payload.body?.slice(0,100) };\n          break;\n        }\n\n        case \"update_store_description\": {\n          result = await (prisma.store as any).update({\n            where: { id: storeId },\n            data: { description: action.payload.description },\n          });\n          break;\n        }\n\n        case \"set_product_status\": {\n          result = await (prisma.product as any).update({\n            where: { id: action.payload.productId },\n            data: { status: action.payload.status || \"ACTIVE\" },\n          });\n          break;\n        }\n\n        case \"update_product_image\": {\n          // Add image URL to existing product\n          const existing = await prisma.product.findUnique({ where: { id: action.payload.productId } });\n          if (!existing) throw new Error(\"Product not found\");\n          const currentImages: string[] = (existing.images as string[]) || [];\n          const newImages = action.payload.imageUrl\n            ? [...new Set([action.payload.imageUrl, ...currentImages])]\n            : currentImages;\n          result = await prisma.product.update({\n            where: { id: action.payload.productId },\n            data: { images: newImages },\n          });\n          break;\n        }\n\n        case \"update_product\": {\n          // Update any product fields\n          const updateData: any = {};\n          if (action.payload.name)        updateData.name        = action.payload.name;\n          if (action.payload.price)       updateData.price       = Number(action.payload.price);\n          if (action.payload.description) updateData.description = action.payload.description;\n          if (action.payload.inventory !== undefined) updateData.inventory = Number(action.payload.inventory);\n          if (action.payload.category)    updateData.category    = action.payload.category;\n          result = await prisma.product.update({\n            where: { id: action.payload.productId },\n            data:  updateData,\n          });\n          break;\n        }\n\n        default:\n          result = { note: `Action ${action.type} logged for manual execution` };\n      }\n      await (prisma.kaiActionLog as any).create({\n        data: { storeId, conversationId: conversationId || \"\", actionType: action.type,\n          payload: action.payload, approved: true, executed: true, result },\n      });\n      // Get product name from the result if available (avoid UUID leak)\n      const resultName = result?.name || result?.code || action.payload?.name || action.payload?.code || \"\";\n      const resultPrice = result?.price || action.payload?.price;\n      const sym2 = \"₦\"; // default; full ctx not in scope here\n      const priceStr = resultPrice ? `${sym2}${Number(resultPrice).toLocaleString()}` : \"\";\n      \n      let successMsg = \"\";\n      if (action.type === \"update_price\" && resultName && priceStr) {\n        successMsg = `${resultName} is now priced at ${priceStr}.`;\n      } else if (action.type === \"update_price\" && priceStr) {\n        successMsg = `Price updated to ${priceStr}.`;\n      } else if (action.type === \"add_product\" && resultName) {\n        successMsg = `\"${resultName}\" is now live in your store${priceStr ? ` at ${priceStr}` : \"\"}.`;\n      } else if (action.type === \"create_coupon\" && result?.code) {\n        successMsg = `Discount code \"${result.code}\" is ready. Customers can use it at checkout.`;\n      } else if (action.type === \"fulfill_order\") {\n        successMsg = \"Order fulfilled. The customer has been notified.\";\n      } else {\n        const desc2 = describeAction(action.type, action.payload, \"₦\");\n        successMsg = desc2.successMessage;\n      }\n      \n      const desc = describeAction(action.type, action.payload, \"₦\");\n      results.push({\n        actionId:  action.id,\n        type:      action.type,\n        success:   true,\n        result,\n        message:   successMsg || desc.successMessage,\n        title:     desc.title,\n        icon:      desc.icon,\n      });\n      // Self-evaluation log — KIRO tracks what it does\n      (prisma.kaiActionLog as any).create({\n        data: {\n          storeId,\n          conversationId: req.body.conversationId || null,\n          actionType: action.type,\n          payload: action.payload,\n          approved: true,\n          executed: true,\n          result: { success: true, message: desc.successMessage },\n        }\n      }).catch(() => {});\n    } catch (err: any) {\n      const humanError = translateError(action.type, err.message || \"unknown error\");\n      results.push({\n        actionId: action.id,\n        type:     action.type,\n        success:  false,\n        error:    humanError,\n        rawError: process.env.NODE_ENV === \"development\" ? err.message : undefined,\n      });\n    }\n  }\n  res.json({ success: true, data: results, results }); // dual path for frontend compat\n}\n\n// ── PATCH /api/kai/conversation/:id ──────────────────────────\nexport async function updateConversation(req: Request, res: Response) {\n  try {\n    const { title, pinned, archived } = req.body;\n    const updated = await prisma.kaiConversation.update({\n      where: { id: req.params.id },\n      data: {\n        ...(title    !== undefined && { title }),\n        ...(pinned   !== undefined && { pinned }),\n        ...(archived !== undefined && { archived }),\n      },\n    });\n    res.json({ success: true, data: updated });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversation/:id ─────────────────────────\nexport async function deleteConversation(req: Request, res: Response) {\n  try {\n    await prisma.kaiConversation.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversations/all ────────────────────────\nexport async function deleteAllConversations(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    await prisma.kaiConversation.deleteMany({ where: { storeId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/memories ─────────────────────────────────────\nexport async function getKaiMemories(req: Request, res: Response) {\n  try {\n    const { storeId, category } = req.query as { storeId: string; category?: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const memories = await getMemories(storeId, category);\n    res.json({ success: true, data: memories });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/memory/:key ───────────────────────────────\nexport async function deleteKaiMemory(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    await deleteMemory(storeId, req.params.key);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/pulse ────────────────────────────────────────\nexport async function getPulseAlerts(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const alerts = await getUnreadAlerts(storeId);\n    res.json({ success: true, data: alerts });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── PATCH /api/kai/pulse/:id/read ────────────────────────────\nexport async function readPulseAlert(req: Request, res: Response) {\n  try {\n    await markAlertRead(req.params.id);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/skills ───────────────────────────────────────\nexport async function getSkills(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const skills = await getKaiSkills(storeId);\n    res.json({ success: true, data: skills });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills ──────────────────────────────────────\nexport async function createSkill(req: Request, res: Response) {\n  try {\n    const { storeId, name, prompt, description, icon, variables } = req.body;\n    if (!storeId || !name || !prompt) return res.status(400).json({ success: false, message: \"storeId, name, prompt required\" });\n    const skill = await (prisma.kaiSkill as any).create({\n      data: { storeId, name, prompt, description, icon, variables: variables || [] },\n    });\n    res.json({ success: true, data: skill });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/skills/:id ────────────────────────────────\nexport async function deleteSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills/:id/use ─────────────────────────────\nexport async function useSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.update({\n      where: { id: req.params.id },\n      data: { usageCount: { increment: 1 } },\n    });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/analyze-voice ───────────────────────────────\nexport async function analyzeVoice(req: Request, res: Response) {\n  try {\n    const { storeId, content } = req.body;\n    if (!storeId || !content) return res.status(400).json({ success: false, message: \"storeId and content required\" });\n    await analyzeBrandVoice(storeId, content, apiKey());\n    res.json({ success: true, message: \"Brand voice analyzed and saved\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/goals ────────────────────────────────────────\nexport async function getGoals(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const goals = await prisma.kaiGoal.findMany({\n      where: { storeId },\n      \n      orderBy: { deadline: \"asc\" },\n    });\n    res.json({ success: true, data: goals });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/goals ───────────────────────────────────────\nexport async function createGoal(req: Request, res: Response) {\n  try {\n    const { storeId, title, targetValue, unit, deadline, description } = req.body;\n    const userId = (req as any).user?.userId || (req as any).user?.id;\n    if (!storeId || !title || !targetValue || !deadline)\n      return res.status(400).json({ success: false, message: \"storeId, title, targetValue, deadline required\" });\n\n    const goal = await (prisma.kaiGoal as any).create({\n      data: { storeId, userId, title, description, targetValue, unit: unit || \"NGN\", deadline: new Date(deadline) },\n      \n    });\n\n    // Save to memory\n    await saveMemory(storeId, \"goal\", `goal_${goal.id}`,\n      `Owner wants to ${title} by ${new Date(deadline).toLocaleDateString()}`, 1.0);\n\n    res.json({ success: true, data: goal });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/morning-brief — proactive daily summary ─────────────────────\nexport async function getMorningBrief(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success:false, message:\"storeId required\" });\n\n    const ctx = await getDeepContext(storeId);\n    const memories = await getMemoryContext(storeId).catch(() => \"\");\n    const sym = ctx.currencySymbol;\n\n    // Build a contextual brief\n    const today = new Date().toLocaleDateString(\"en-NG\", { weekday:\"long\", day:\"numeric\", month:\"long\" });\n    const hour  = new Date().getHours();\n    const greeting = hour < 12 ? \"Good morning\" : hour < 17 ? \"Good afternoon\" : \"Good evening\";\n\n    const lines: string[] = [];\n    lines.push(`${greeting} 👋 Here's your store update for ${today}:`);\n    lines.push(\"\");\n    lines.push(`💰 Revenue today: ${sym}${(ctx.revenueToday||0).toLocaleString()}`);\n    lines.push(`📦 Orders: ${ctx.totalOrders} total, ${ctx.pendingOrders} pending`);\n    lines.push(`🛍️ Products: ${ctx.activeProducts} active`);\n    if (ctx.lowStockProducts.length > 0) lines.push(`⚠️ ${ctx.lowStockProducts.length} products are low on stock: ${ctx.lowStockProducts.slice(0,3).map((p:any)=>p.name||p).join(\", \")}`);\n    lines.push(\"\");\n\n    if (ctx.pendingOrders > 0) {\n      lines.push(`🚨 You have ${ctx.pendingOrders} unfulfilled orders. Fulfill them now to build trust.`);\n    } else if (ctx.revenueToday === 0) {\n      lines.push(`Your store has ₦0 in sales today. Want me to suggest a quick push strategy?`);\n    } else {\n      lines.push(`Things are moving. Keep the momentum going.`);\n    }\n\n    res.json({ success:true, data: { brief: lines.join(\"\\n\"), ctx, date: today } });\n  } catch(err:any) {\n    res.status(500).json({ success:false, message:err.message });\n  }\n}\n\n", "frontend/src/components/kai/KAIChat.tsx": "\"use client\";\nimport { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api, uploadAPI } from \"../../lib/api\";\nimport {\n  Send, Paperclip, X, Loader2, Copy, Check, ChevronDown,\n  Image, FileText, Zap, RefreshCw, Trash2\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\nconst BASE = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\n\ninterface Message {\n  id: string;\n  role: \"user\" | \"assistant\";\n  content: string;\n  isStreaming?: boolean;\n  imageUrl?: string;\n  fileName?: string;\n  actions?: any[];\n  timestamp?: string;\n}\n\ninterface KIROChatProps {\n  className?: string;\n  storeId?: string;\n  initialMessage?: string;\n  compact?: boolean;\n  conversationId?: string;\n  onConversationCreated?: (id: string) => void;\n}\n\n// ── Human-readable action descriptions (mirrors kai.actions.ts) ───────────────\nfunction getActionDesc(type: string, payload: any, symbol = \"₦\") {\n  const fmt = (n: number) => `${symbol}${(n||0).toLocaleString()}`;\n  const map: Record<string, {title:string; summary:string; icon:string; cta:string}> = {\n    add_product:           { icon:\"📦\", cta:\"Add to Store\",   title:\"New Product\",          summary:`Add \"${payload?.name}\" at ${fmt(payload?.price)}` },\n    bulk_add_products:     { icon:\"📥\", cta:\"Import All\",     title:\"Bulk Import\",           summary:`Import ${payload?.products?.length || 0} products` },\n    update_price:          { icon:\"💰\", cta:\"Update Price\",   title:\"Price Change\",          summary:`Change price to ${fmt(payload?.price)}` },\n    update_stock:          { icon:\"📦\", cta:\"Update Stock\",   title:\"Stock Update\",          summary:`Set inventory to ${payload?.quantity} units` },\n    archive_product:       { icon:\"🔒\", cta:\"Hide Product\",   title:\"Hide from Store\",       summary:\"Remove this product from your public store\" },\n    set_product_status:    { icon:payload?.status===\"ACTIVE\"?\"✅\":\"📴\", cta:payload?.status===\"ACTIVE\"?\"Activate\":\"Archive\", title:payload?.status===\"ACTIVE\"?\"Activate Product\":\"Archive Product\", summary:payload?.status===\"ACTIVE\"?\"Make product visible to customers\":\"Hide product from customers\" },\n    create_coupon:         { icon:\"🎟️\", cta:\"Create Code\",   title:\"Discount Code\",         summary:`Create code \"${payload?.code}\" — ${payload?.discount||payload?.discountValue}% off` },\n    fulfill_order:         { icon:\"🚚\", cta:\"Fulfill Order\",  title:\"Fulfill Order\",         summary:\"Mark as fulfilled and notify customer\" },\n    update_order_status:   { icon:\"📋\", cta:\"Update Status\", title:\"Order Update\",          summary:`Set status to ${(payload?.status||\"\").toLowerCase()}` },\n    create_flash_sale:     { icon:\"⚡\", cta:\"Launch Sale\",   title:\"Flash Sale\",            summary:`${payload?.discountPercent}% off on ${payload?.productIds?.length||0} products` },\n    update_store_description:{ icon:\"✏️\",cta:\"Update\",       title:\"Store Description\",     summary:\"Update your public store description\" },\n    update_product_image:      { icon:\"📷\",cta:\"Add Image\",      title:\"Add Product Image\",      summary:`Add image to ${payload?.productId ? \"product\" : \"\"}` },\n    update_product:            { icon:\"✏️\",cta:\"Update Product\", title:\"Update Product\",         summary:\"Apply changes to this product\" },\n    get_analytics:         { icon:\"📈\", cta:\"Run Report\",    title:\"Analytics Report\",      summary:\"Pull your latest store performance data\" },\n    export_orders:         { icon:\"📤\", cta:\"Export\",        title:\"Export Orders\",         summary:\"Download your order history\" },\n  };\n  return map[type] || { icon:\"⚡\", cta:\"Execute\", title:type.replace(/_/g,\" \").replace(/\b\\w/g,c=>c.toUpperCase()), summary:\"Execute this action\" };\n}\n\nfunction ActionCard({ action, onApprove, onDismiss, t, isDark }: any) {\n  const [loading, setLoading] = useState(false);\n  const [done,    setDone]    = useState(false);\n  const desc = getActionDesc(action.type, action.payload);\n\n  const approve = async () => {\n    setLoading(true);\n    await onApprove(action);\n    setDone(true);\n    setLoading(false);\n  };\n\n  if (done) return null; // Remove card after approval — result shown in chat\n\n  return (\n    <motion.div initial={{opacity:0,y:6}} animate={{opacity:1,y:0}}\n      style={{ marginTop:12, borderRadius:16, overflow:\"hidden\",\n        border: `1px solid ${isDark?\"rgba(107,53,232,0.25)\":\"rgba(107,53,232,0.15)\"}`,\n        background: isDark?\"rgba(107,53,232,0.06)\":\"rgba(107,53,232,0.03)\" }}>\n      {/* Header */}\n      <div style={{ padding:\"12px 14px 10px\", borderBottom:`1px solid ${isDark?\"rgba(107,53,232,0.12)\":\"rgba(107,53,232,0.08)\"}` }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n          <span style={{ fontSize:18 }}>{desc.icon}</span>\n          <div>\n            <p style={{ fontSize:12, fontWeight:800, color:V.v400, margin:0, letterSpacing:\"-0.01em\" }}>{desc.title}</p>\n            <p style={{ fontSize:12, color:t.muted, margin:0, lineHeight:1.4, marginTop:2 }}>{desc.summary}</p>\n          </div>\n        </div>\n      </div>\n      {/* Actions */}\n      <div style={{ padding:\"10px 14px\", display:\"flex\", gap:8, alignItems:\"center\" }}>\n        <button onClick={approve} disabled={loading}\n          style={{ padding:\"8px 18px\", borderRadius:10, border:\"none\",\n            background:loading?\"rgba(107,53,232,0.4)\":`linear-gradient(135deg,${V.v500},#3D1C8A)`,\n            color:\"#fff\", fontSize:12, fontWeight:700, cursor:loading?\"not-allowed\":\"pointer\",\n            fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", gap:6, flexShrink:0,\n            boxShadow:loading?\"none\":\"0 2px 8px rgba(107,53,232,0.3)\" }}>\n          {loading\n            ? <><Loader2 size={11} style={{animation:\"spin 0.8s linear infinite\"}}/> Working...</>\n            : <><Check size={11}/> {desc.cta}</>}\n        </button>\n        <button onClick={()=>onDismiss(action)}\n          style={{ padding:\"8px 14px\", borderRadius:10, border:`1px solid ${t.border}`,\n            background:\"transparent\", color:t.muted, fontSize:12, cursor:\"pointer\", fontFamily:\"inherit\" }}>\n          Dismiss\n        </button>\n        <p style={{ fontSize:11, color:t.muted, margin:\"0 0 0 auto\", fontStyle:\"italic\" }}>Review before confirming</p>\n      </div>\n    </motion.div>\n  );\n}\n\n\n// Strip KIRO internal formatting from user-visible text\nfunction cleanKIROContent(text: string): string {\n  return text\n    .replace(/KIRO_ACTION[:\\s]+\\{[\\s\\S]*?\\}(?=\\n|$)/g, \"\")   // strip action blocks\n    .replace(/━+/g, \"\")                                           // strip divider chars\n    .replace(/^[-=]{3,}\\s*$/gm, \"\")                              // strip --- === lines\n    .replace(/\\n{3,}/g, \"\\n\\n\")                                  // collapse 3+ newlines\n    .trim();\n}\n\nfunction MessageBubble({ msg, onApprove, onDismiss, t, isDark }: any) {\n  const [copied, setCopied] = useState(false);\n  const isUser = msg.role === \"user\";\n\n  const copy = () => {\n    navigator.clipboard.writeText(msg.content);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n      style={{ display:\"flex\", flexDirection: isUser?\"row-reverse\":\"row\", gap:10, alignItems:\"flex-start\", marginBottom:16 }}>\n\n      {/* Avatar */}\n      {!isUser && (\n        <div style={{ width:30, height:30, borderRadius:10, background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, boxShadow:`0 4px 12px ${V.v500}40` }}>\n          <Zap size={13} color=\"#fff\" fill=\"#fff\"/>\n        </div>\n      )}\n\n      <div style={{ maxWidth:\"82%\", minWidth:40 }}>\n        {/* Image attachment */}\n        {msg.imageUrl && (\n          <img src={msg.imageUrl} alt=\"attachment\"\n            style={{ maxWidth:\"100%\", maxHeight:200, borderRadius:12, marginBottom:6, objectFit:\"cover\", display:\"block\" }}/>\n        )}\n        {msg.fileName && !msg.imageUrl && (\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"6px 10px\", borderRadius:8, background:isDark?\"rgba(255,255,255,0.06)\":\"#f5f3ff\", marginBottom:6, fontSize:11, color:t.muted }}>\n            <FileText size={12}/> {msg.fileName}\n          </div>\n        )}\n\n        {/* Message bubble */}\n        <div style={{\n          padding: isUser?\"10px 14px\":\"2px 0\",\n          borderRadius: isUser?\"16px 16px 4px 16px\":\"0\",\n          background: isUser?`linear-gradient(135deg,${V.v500},#3D1C8A)`:\"transparent\",\n          color: isUser?\"#fff\":t.text,\n          fontSize: 14,\n          lineHeight: 1.65,\n          position:\"relative\",\n        }}>\n          {msg.isStreaming && !msg.content ? (\n            <span style={{ display:\"flex\", alignItems:\"center\", gap:8, color:t.muted }}>\n              <span style={{ display:\"flex\", gap:3 }}>\n                {[0,1,2].map(i => (\n                  <motion.span key={i} style={{ width:6, height:6, borderRadius:\"50%\", background:V.v400, display:\"block\" }}\n                    animate={{ y:[0,-4,0] }} transition={{ duration:0.6, repeat:Infinity, delay:i*0.15 }}/>\n                ))}\n              </span>\n              <span style={{ fontSize:13 }}>KIRO is thinking</span>\n            </span>\n          ) : msg.isStreaming && msg.content ? (\n            <p style={{ margin:0, whiteSpace:\"pre-wrap\", wordBreak:\"break-word\" }}>\n              {cleanKIROContent(msg.content || \"\")}\n              <motion.span animate={{ opacity:[1,0] }} transition={{ duration:0.5, repeat:Infinity }}>▋</motion.span>\n            </p>\n          ) : (\n            <p style={{ margin:0, whiteSpace:\"pre-wrap\", wordBreak:\"break-word\" }}>{cleanKIROContent(msg.content || \"\")}</p>\n          )}\n\n          {/* Action cards */}\n          {msg.actions?.map((action: any, i: number) => (\n            <ActionCard key={i} action={action} onApprove={onApprove} onDismiss={onDismiss} t={t} isDark={isDark}/>\n          ))}\n\n          {/* Copy button */}\n          {!isUser && !msg.isStreaming && msg.content && (\n            <button onClick={copy}\n              style={{ position:\"absolute\", top:0, right:-28, width:22, height:22, borderRadius:6, border:`1px solid ${t.border}`, background:t.card, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", opacity:0.5 }}>\n              {copied ? <Check size={11} color={V.v400}/> : <Copy size={11} color={t.muted}/>}\n            </button>\n          )}\n        </div>\n\n        {msg.timestamp && !msg.isStreaming && (\n          <p style={{ fontSize:10, color:t.muted, margin:\"3px 0 0\", textAlign:isUser?\"right\":\"left\" }}>\n            {new Date(msg.timestamp).toLocaleTimeString(\"en-NG\",{hour:\"2-digit\",minute:\"2-digit\"})}\n          </p>\n        )}\n      </div>\n    </motion.div>\n  );\n}\n\nexport default function KIROChat({ storeId: propStoreId, initialMessage, compact, conversationId: initConvId, onConversationCreated }: KIROChatProps) {\n  const { user } = useAuthStore();\n  const token  = useAuthStore(s => s.accessToken);\n  const storeId = propStoreId || user?.stores?.[0]?.id || \"\";\n\n  const [messages,    setMessages]    = useState<Message[]>([]);\n  const [input,       setInput]       = useState(initialMessage || \"\");\n  const [greeting,    setGreeting]    = useState<any>(null);\n  const [loading,     setLoading]     = useState(false);\n  const [convId,      setConvId]      = useState(initConvId || \"\");\n  const [attachment,  setAttachment]  = useState<{url?:string; cloudUrl?:string; base64?:string; type?:string; name?:string}|null>(null);\n  const [uploading,   setUploading]   = useState(false);\n  const [histLoaded,  setHistLoaded]  = useState(false);\n\n  const bottomRef = useRef<HTMLDivElement>(null);\n  const inputRef  = useRef<HTMLTextAreaElement>(null);\n  const abortRef  = useRef<AbortController|null>(null);\n  const fileRef   = useRef<HTMLInputElement>(null);\n\n  // Theme detection\n  const isDark = typeof document !== \"undefined\" && document.documentElement.classList.contains(\"dark\");\n  const t = {\n    bg:    isDark?\"#07050F\":\"#F4F2FB\",\n    card:  isDark?\"#181230\":\"#fff\",\n    border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text:  isDark?\"#F0ECFF\":\"#130D2E\",\n    muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    input: isDark?\"rgba(255,255,255,0.05)\":\"#fff\",\n  };\n\n  // ── Load conversation history on mount ──────────────────────────────────────\n  useEffect(() => {\n    if (!storeId || histLoaded) return;\n    setHistLoaded(true);\n\n    // If we have a specific conversationId, load it\n    if (convId) {\n      api.get(`/kai/conversation/${convId}`)\n        .then(r => {\n          const conv = r.data?.data;\n          if (conv?.messages?.length) {\n            setMessages(conv.messages.map((m: any) => ({\n              id:        m.id,\n              role:      m.role,\n              content:   m.content,\n              timestamp: m.createdAt,\n            })));\n          }\n        })\n        .catch(() => {});\n    } else {\n      // Load the most recent conversation for this store\n      api.get(`/kai/conversations?storeId=${storeId}`)\n        .then(r => {\n          const convs = r.data?.data || [];\n          if (convs.length > 0) {\n            const latest = convs[0];\n            setConvId(latest.id);\n            if (latest.messages?.length) {\n              setMessages(latest.messages.map((m: any) => ({\n                id:        m.id,\n                role:      m.role,\n                content:   m.content,\n                timestamp: m.createdAt,\n              })));\n            } else {\n              // Load full conversation\n              api.get(`/kai/conversation/${latest.id}`)\n                .then(r2 => {\n                  const msgs = r2.data?.data?.messages || [];\n                  setMessages(msgs.map((m: any) => ({\n                    id: m.id, role: m.role, content: m.content, timestamp: m.createdAt,\n                  })));\n                })\n                .catch(() => {});\n            }\n          }\n        })\n        .catch(() => {});\n    }\n  }, [storeId, convId, histLoaded]);\n\n  useEffect(() => {\n    // Use requestAnimationFrame for smooth scroll during streaming\n    const el = bottomRef.current;\n    if (el) requestAnimationFrame(() => el.scrollIntoView({ behavior: \"smooth\", block: \"end\" }));\n  }, [messages]);\n\n  // ── File upload ──────────────────────────────────────────────────────────────\n  const handleFile = async (file: File) => {\n    const isImage = file.type.startsWith(\"image/\");\n    const isPDF   = file.type === \"application/pdf\";\n    const isCSV   = file.type === \"text/csv\" || file.name.endsWith(\".csv\");\n\n    if (!isImage && !isPDF && !isCSV) {\n      toast.error(\"Only images, PDFs, and CSV files are supported\");\n      return;\n    }\n\n    setUploading(true);\n    try {\n      if (isImage) {\n        // Read as data URI locally — no network roundtrip, works offline\n        // The base64 is sent directly to KIRO for vision analysis\n        const dataUrl = await new Promise<string>((resolve, reject) => {\n          const reader = new FileReader();\n          reader.onload  = () => resolve(reader.result as string);\n          reader.onerror = () => reject(new Error(\"Could not read file\"));\n          reader.readAsDataURL(file);\n        });\n        setAttachment({ url: dataUrl, type:\"image\", name:file.name });\n      } else {\n        // Read as base64 for PDF/CSV\n        const base64 = await new Promise<string>((res,rej) => {\n          const r = new FileReader();\n          r.onload  = () => res((r.result as string).split(\",\")[1]);\n          r.onerror = rej;\n          r.readAsDataURL(file);\n        });\n        setAttachment({ base64, type: isPDF?\"pdf\":\"csv\", name:file.name });\n      }\n    } catch {\n      toast.error(\"Upload failed\");\n    } finally {\n      setUploading(false);\n    }\n  };\n\n  // ── Execute approved action ──────────────────────────────────────────────────\n  const handleApprove = async (action: any) => {\n    try {\n      const res = await api.post(\"/kai/action\", {\n        storeId, conversationId: convId,\n        actions: [{ ...action, approved: true }],\n      });\n      const result = (res.data?.data || res.data?.results)?.[0];\n      // Use human-readable messages from the server\n      const resultMsg: Message = {\n        id:        `action-${Date.now()}`,\n        role:      \"assistant\",\n        content:   result?.success\n          ? (result?.message || `Done. ${action.type.replace(/_/g,\" \")} completed.`)\n          : (result?.error   || \"Something didn't go as expected. Let me check what went wrong and try again.\"),\n        timestamp: new Date().toISOString(),\n      };\n      setMessages(p => [...p, resultMsg]);\n    } catch(e:any) {\n      toast.error(e.response?.data?.message || \"Action failed\");\n    }\n  };\n\n  const handleDismiss = (action: any) => {\n    setMessages(p => p.map(m => ({\n      ...m,\n      actions: m.actions?.filter(a => a !== action),\n    })));\n  };\n\n  // ── Send message ─────────────────────────────────────────────────────────────\n  const sendMessage = async (msg: string) => {\n    if (!msg.trim() || loading) return;\n    setInput(\"\");\n    const syntheticEvent = { target: { value: msg } } as any;\n    // Directly call the send logic with the provided message\n    const text = msg.trim();\n    if (!storeId) { toast.error(\"No store connected\"); return; }\n\n    // Build user message\n    const userMsg: Message = {\n      id:        `u-${Date.now()}`,\n      role:      \"user\",\n      content:   text,\n      timestamp: new Date().toISOString(),\n    };\n    setMessages(p => [...p, userMsg]);\n\n    const kiroMsg: Message = {\n      id:          `k-${Date.now()}`,\n      role:        \"assistant\",\n      content:     \"\",\n      isStreaming: true,\n      timestamp:   new Date().toISOString(),\n    };\n    setMessages(p => [...p, kiroMsg]);\n    setLoading(true);\n\n    // Start KIRO (same as send but with provided text)\n    const convId = initConvId || \"\";\n    const BASE = (process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\");\n    const token = useAuthStore.getState().accessToken;\n    const body: any = { message: text, storeId, sessionId: convId || undefined };\n\n    try {\n      const streamRes = await fetch(`${BASE}/kai/smart-chat`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\", ...(token ? { Authorization: `Bearer ${token}` } : {}), Accept: \"text/event-stream\" },\n        body: JSON.stringify(body),\n        signal: abortRef.current?.signal,\n      });\n\n      if (!streamRes.ok) {\n        const err = await streamRes.json().catch(()=>({message:`Error ${streamRes.status}`}));\n        throw new Error(err.message || `Server error ${streamRes.status}`);\n      }\n\n      const isStream = streamRes.headers.get(\"content-type\")?.includes(\"text/event-stream\");\n      let full = \"\";\n      if (isStream) {\n        const reader = streamRes.body!.getReader();\n        const decoder = new TextDecoder();\n        while (true) {\n          const { done, value } = await reader.read();\n          if (done) break;\n          const chunk = decoder.decode(value, { stream: true });\n          const lines = chunk.split(\"\\n\");\n          for (const line of lines) {\n            if (!line.startsWith(\"data:\")) continue;\n            const raw = line.slice(5).trim();\n            if (!raw) continue;\n            try {\n              const parsed = JSON.parse(raw);\n              if (parsed.token) { full += parsed.token; setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content: cleanKIROContent(full) } : m)); }\n              if (parsed.conversationId && !convId) { setConvId(parsed.conversationId); onConversationCreated?.(parsed.conversationId); }\n              if (parsed.actions?.length) { setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, actions:parsed.actions } : m)); }\n              if (parsed.done) {\n                const raw2 = parsed.cleanResponse || \"\";\n                const fc = raw2 ? cleanKIROContent(raw2) : undefined;\n                const fa = parsed.actions || [];\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, isStreaming:false, ...(fc?{content:fc}:{}), ...(fa.length?{actions:fa}:{}) } : m));\n              }\n              if (parsed.error) throw new Error(parsed.message || \"KIRO error\");\n            } catch(e:any) { if (e.message && !e.message.includes(\"JSON\")) throw e; }\n          }\n        }\n      }\n      setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, isStreaming:false, content:cleanKIROContent(full)||m.content } : m));\n    } catch(e:any) {\n      if (e.name === \"AbortError\") {\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:\"Cancelled.\", isStreaming:false } : m));\n      } else {\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:e.message||\"Something went wrong.\", isStreaming:false } : m));\n      }\n    } finally { setLoading(false); }\n  };\n\n  const send = async () => {\n    const text = input.trim();\n    if (!text && !attachment) return;\n    if (loading || !storeId) return;\n\n    abortRef.current?.abort();\n    abortRef.current = new AbortController();\n\n    const displayText = text || (attachment ? \"📎 \" + (attachment.name || \"Image\") : \"\");\n    const userMsg: Message = {\n      id:        `u-${Date.now()}`,\n      role:      \"user\",\n      content:   displayText,\n      imageUrl:  attachment?.url,\n      fileName:  !attachment?.url ? attachment?.name : undefined,\n      timestamp: new Date().toISOString(),\n    };\n    const kiroMsg: Message = {\n      id:          `k-${Date.now()}`,\n      role:        \"assistant\",\n      content:     \"\",\n      isStreaming: true,\n      timestamp:   new Date().toISOString(),\n    };\n\n    setMessages(p => [...p, userMsg, kiroMsg]);\n    setInput(\"\");\n    setAttachment(null);\n    setLoading(true);\n\n    try {\n      // Build message - if only image, add a default prompt\n      const finalMessage = text || (attachment ? \"Please analyse this image and help me use it in my store.\" : \"\");\n      \n      const body: any = { message: finalMessage, storeId, sessionId: convId || undefined };\n      \n      if (attachment?.url) {\n        if (attachment.url.startsWith(\"data:image/\")) {\n          // Extract base64 from data URI for KIRO vision\n          const parts  = attachment.url.split(\",\");\n          const mime   = parts[0].split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n          body.imageBase64      = parts[1];\n          body.imageMediaType   = mime;\n          body.imageUrl         = attachment.url; // for display\n        } else {\n          // Cloudinary URL - send as URL reference\n          body.imageUrl         = attachment.url;\n          body.message          = finalMessage + `\\n\\n[Image: ${attachment.url}]`;\n        }\n      }\n      if (attachment?.base64) {\n        body.fileBase64  = attachment.base64;\n        body.fileType    = attachment.type;\n      }\n      if (attachment?.name)   body.fileName    = attachment.name;\n\n      const streamRes = await fetch(`${BASE}/kai/smart-chat`, {\n        method:  \"POST\",\n        headers: {\n          \"Content-Type\":  \"application/json\",\n          \"Authorization\": `Bearer ${token}`,\n          \"Accept\":        \"text/event-stream\",\n        },\n        body:   JSON.stringify(body),\n        signal: abortRef.current.signal,\n      });\n\n      if (!streamRes.ok) {\n        const err = await streamRes.json().catch(()=>({message:`Error ${streamRes.status}`}));\n        throw new Error(err.message || `Server error ${streamRes.status}`);\n      }\n\n      const isStream = streamRes.headers.get(\"content-type\")?.includes(\"text/event-stream\");\n\n      if (isStream) {\n        const reader  = streamRes.body!.getReader();\n        const decoder = new TextDecoder();\n        let full = \"\";\n\n        while (true) {\n          const { done, value } = await reader.read();\n          if (done) break;\n          const chunk = decoder.decode(value, { stream:true });\n          const lines = chunk.split(\"\\n\");\n          for (const line of lines) {\n            if (!line.startsWith(\"data:\")) continue;\n            const raw = line.slice(5).trim();\n            if (!raw) continue;\n            try {\n              const parsed = JSON.parse(raw);\n              if (parsed.token) {\n                full += parsed.token;\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:full } : m));\n              }\n              if (parsed.conversationId && !convId) {\n                setConvId(parsed.conversationId);\n                onConversationCreated?.(parsed.conversationId);\n              }\n              if (parsed.actions?.length) {\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, actions:parsed.actions } : m));\n              }\n              if (parsed.done) {\n                // Use clean response — strip KIRO_ACTION + ugly divider lines\n                const rawContent = parsed.cleanResponse || \"\";\n                const finalContent = rawContent\n                  .replace(/━+/g, \"\")\n                  .replace(/^-{3,}\\s*$/gm, \"\")\n                  .replace(/^={3,}\\s*$/gm, \"\")\n                  .replace(/\\n{3,}/g, \"\\n\\n\")\n                  .trim() || undefined;\n                const finalActions = parsed.actions || [];\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? {\n                  ...m,\n                  isStreaming: false,\n                  ...(finalContent ? { content: finalContent } : {}),\n                  ...(finalActions.length ? { actions: finalActions } : {}),\n                } : m));\n              }\n              if (parsed.error) {\n                throw new Error(parsed.message || \"KIRO error\");\n              }\n            } catch(e: any) {\n              if (e.message && !e.message.includes(\"JSON\")) throw e;\n            }\n          }\n        }\n\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, isStreaming:false, content:full||m.content } : m));\n\n      } else {\n        // Non-streaming fallback\n        const data = await streamRes.json();\n        const reply = data.data?.message || data.message || \"No response\";\n        if (data.data?.conversationId && !convId) {\n          setConvId(data.data.conversationId);\n          onConversationCreated?.(data.data.conversationId);\n        }\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? {\n          ...m, content:reply, isStreaming:false,\n          actions: data.data?.actions || [],\n        } : m));\n      }\n\n    } catch(e: any) {\n      if (e.name === \"AbortError\") {\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:\"Cancelled.\", isStreaming:false } : m));\n      } else {\n        const errMsg = e.message || \"Something went wrong. Check your connection.\";\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:errMsg, isStreaming:false } : m));\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const clear = () => { setMessages([]); setConvId(\"\"); setHistLoaded(false); };\n\n  const handleKey = (e: React.KeyboardEvent) => {\n    if (e.key === \"Enter\" && !e.shiftKey) { e.preventDefault(); send(); }\n  };\n\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", position:\"relative\", fontFamily:\"system-ui,sans-serif\" }}>\n\n      {/* Messages */}\n      <div style={{ flex:1, overflowY:\"auto\", padding:compact?\"12px\":\"16px 20px\" }}>\n        {messages.length === 0 && (\n          <div style={{ padding:\"32px 20px 20px\" }}>\n            {/* KIRO greeting */}\n            <div style={{ display:\"flex\", gap:12, marginBottom:20 }}>\n              <div style={{ width:36, height:36, borderRadius:12, background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n                <Zap size={16} color=\"#fff\" fill=\"#fff\"/>\n              </div>\n              <div style={{ background:isDark?\"rgba(107,53,232,0.08)\":\"#F4F1FF\", borderRadius:\"4px 16px 16px 16px\", padding:\"12px 16px\", maxWidth:\"85%\" }}>\n                <p style={{ fontSize:14, color:t.text, margin:\"0 0 6px\", lineHeight:1.6, fontWeight:500 }}>\n                  {greeting?.contextLine || \"What are we working on today?\"}\n                </p>\n                {greeting?.storeContext?.pendingOrders > 0 && (\n                  <p style={{ fontSize:13, color:\"#EF4444\", margin:\"4px 0 0\", fontWeight:600 }}>\n                    ⚠️ {greeting.storeContext.pendingOrders} order{greeting.storeContext.pendingOrders > 1 ? \"s\" : \"\"} pending — needs attention.\n                  </p>\n                )}\n              </div>\n            </div>\n            {/* Quick action suggestions */}\n            <div style={{ display:\"flex\", gap:8, flexWrap:\"wrap\", paddingLeft:48 }}>\n              {(greeting?.quickActions?.length ? greeting.quickActions.map((a: any) => a.prompt) : [\n                \"What should I focus on today?\",\n                \"What products are trending in Nigeria?\",\n                \"Write me an Instagram caption\",\n                \"Show my pending orders\",\n              ]).map((prompt: string) => (\n                <button key={prompt} onClick={() => sendMessage(prompt)}\n                  style={{ padding:\"6px 14px\", borderRadius:99, border:`1px solid ${t.border}`, background:t.card, color:t.text, fontSize:12, cursor:\"pointer\", fontFamily:\"inherit\", whiteSpace:\"nowrap\" }}>\n                  {prompt.length > 38 ? prompt.slice(0,38) + \"…\" : prompt}\n                </button>\n              ))}\n            </div>\n          </div>\n        )}\n\n        {messages.map(msg => (\n          <MessageBubble key={msg.id} msg={msg} onApprove={handleApprove} onDismiss={handleDismiss} t={t} isDark={isDark}/>\n        ))}\n        <div ref={bottomRef}/>\n      </div>\n\n      {/* Attachment preview */}\n      {attachment && (\n        <div style={{ padding:\"8px 16px 0\", display:\"flex\", alignItems:\"center\", gap:8 }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"6px 12px\", borderRadius:10, background:`${V.v400}12`, border:`1px solid ${V.v400}30`, flex:1 }}>\n            {attachment.type===\"image\" ? <Image size={13} color={V.v400}/> : <FileText size={13} color={V.v400}/>}\n            <span style={{ fontSize:12, color:t.text, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{attachment.name}</span>\n            {attachment.url && <img src={attachment.url} alt=\"\" style={{ width:28, height:28, borderRadius:6, objectFit:\"cover\", flexShrink:0 }}/>}\n          </div>\n          <button onClick={() => setAttachment(null)} style={{ width:26, height:26, borderRadius:8, border:\"none\", background:\"rgba(239,68,68,0.08)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <X size={12} color=\"#EF4444\"/>\n          </button>\n        </div>\n      )}\n\n      {/* Input bar */}\n      <div style={{ padding:compact?\"8px\":\"12px 16px\", borderTop:`1px solid ${t.border}`, background:t.card }}>\n        <div style={{ display:\"flex\", gap:8, alignItems:\"flex-end\", padding:\"10px 12px\", borderRadius:16, border:`1.5px solid ${loading?V.v400:t.border}`, background:t.input, transition:\"border-color 0.2s\" }}>\n          {/* Attach button */}\n          <button onClick={() => fileRef.current?.click()} disabled={uploading}\n            style={{ width:30, height:30, borderRadius:8, border:`1px solid ${t.border}`, background:\"transparent\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, opacity:uploading?0.5:1 }}>\n            {uploading ? <Loader2 size={14} color={t.muted} style={{animation:\"spin 0.8s linear infinite\"}}/> : <Paperclip size={14} color={t.muted}/>}\n          </button>\n\n          <textarea\n            ref={inputRef}\n            value={input}\n            onChange={e => setInput(e.target.value)}\n            onKeyDown={handleKey}\n            placeholder=\"Ask KIRO anything...\"\n            rows={1}\n            style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", resize:\"none\", fontSize:14, color:t.text, fontFamily:\"inherit\", lineHeight:1.5, maxHeight:120, overflow:\"auto\", paddingTop:2 }}\n            onInput={e => {\n              const el = e.target as HTMLTextAreaElement;\n              el.style.height = \"auto\";\n              el.style.height = Math.min(el.scrollHeight, 120) + \"px\";\n            }}\n          />\n\n          {/* Send / Stop */}\n          <button onClick={loading ? () => abortRef.current?.abort() : send}\n            disabled={!loading && !input.trim() && !attachment}\n            style={{ width:34, height:34, borderRadius:10, border:\"none\", background: loading?\"rgba(239,68,68,0.1)\": (input.trim()||attachment)?`linear-gradient(135deg,${V.v500},#3D1C8A)`:\"rgba(0,0,0,0.05)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, transition:\"all 0.2s\", opacity:(!loading && !input.trim() && !attachment)?0.4:1 }}>\n            {loading\n              ? <X size={14} color=\"#EF4444\"/>\n              : <Send size={14} color={(input.trim()||attachment)?\"#fff\":t.muted}/>}\n          </button>\n        </div>\n\n        <p style={{ fontSize:10, color:t.muted, textAlign:\"center\", marginTop:6, marginBottom:0 }}>\n          KIRO can make mistakes. Always verify important business decisions.\n        </p>\n      </div>\n\n      {/* Hidden file input */}\n      <input ref={fileRef} type=\"file\" accept=\"image/*,.pdf,.csv,.xlsx\"\n        style={{ display:\"none\" }}\n        onChange={e => { if(e.target.files?.[0]) handleFile(e.target.files[0]); e.target.value=\"\"; }}/>\n\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n"};
let n=0;
for(const[r,c] of Object.entries(F)){const p=path.join(process.cwd(),r.replace(/\//g,path.sep));fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');n++;}
